def read_json(f):
    return json.load(open(f,'r'))

data=read_json('json/budget.json')
with open('csv/expense.csv','r') as f:
    expenses=list(csv.DictReader(f))

# Find budgets linked to October Meeting event
oct_budget_ids=set()
for b in data['records']:
    if b['link_to_event']=='recggMW2eyCYceNcy':
        oct_budget_ids.add(b['budget_id'])

print('Budgets for October Meeting:', oct_budget_ids)

# Find approved expenses and sum by type
result={}
for e in expenses:
    if e['link_to_budget'] in oct_budget_ids and e['approved']=='1':
        desc=e['expense_description']
        cost=float(e['cost'])
        result[desc]=result.get(desc,0)+cost

for desc,sum_cost in sorted(result.items()):
    print(f'{desc}: {sum_cost}')
print('Done')

